const { app, BrowserWindow, ipcMain } = require('electron');
const path = require('path');
const fetch = require('node-fetch');
const Store = require('electron-store');

const store = new Store();

function createWindow() {
 const win = new BrowserWindow({
 width: 1400,
 height: 900,
 webPreferences: {
 preload: path.join(__dirname, 'preload.js'),
 contextIsolation: true,
 nodeIntegration: false
 }
 });

 win.loadFile('renderer.html');
}

app.whenReady().then(createWindow);

// ===== LLM ROUTER =====
ipcMain.handle('llm:request', async (_, payload) => {
 const { provider, prompt } = payload;

 if (provider === 'ollama') {
 const res = await fetch('http://localhost:11434/api/generate', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify({ model: 'llama3', prompt })
 });
 const data = await res.json();
 return data.response;
 }

 if (provider === 'openai') {
 const key = store.get('openaiKey');
 const res = await fetch('https://api.openai.com/v1/chat/completions', {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json',
 'Authorization': `Bearer ${key}`
 },
 body: JSON.stringify({
 model: 'gpt-4o-mini',
 messages: [{ role: 'user', content: prompt }]
 })
 });
 const data = await res.json();
 return data.choices[0].message.content;
 }

 return 'Provider not configured';
});

// ===== MEMORY ENGINE =====
ipcMain.handle('memory:save', (_, data) => {
 store.set('memory', data);
});

ipcMain.handle('memory:load', () => {
 return store.get('memory', []);
});
```

