 "type": "module",
 "scripts": {
 "start": "electron ."
 },
 "dependencies": {
 "electron": "^26.0.0"
 }
}

// ============================================================================
// electron/main.js
// ============================================================================
import { app, BrowserWindow, ipcMain } from 'electron'
import path from 'path'
import { fileURLToPath } from 'url'
import { sendLLM } from '../core/llm.js'
import { createMemory, addMemory } from '../core/memory.js'
import { createXP, addXP } from '../core/xp.js'
import { encrypt, decrypt } from '../core/vault.js'

const __filename = fileURLToPath(import.meta.url)
const __dirname = path.dirname(__filename)

let memory = createMemory()
let xp = createXP()

function createWindow() {
 const win = new BrowserWindow({
 width: 1400,
 height: 900,
 webPreferences: {
 preload: path.join(__dirname, 'preload.js'),
 contextIsolation: true
 }
 })

 win.loadFile(path.join(__dirname, '../renderer/index.html'))
}

app.whenReady().then(createWindow)

// ================= IPC =================

ipcMain.handle('llm:send', async (e, payload) => {
 const response = await sendLLM(payload)
 memory = addMemory(memory, { prompt: payload.prompt, response })
 xp = addXP(xp, 15)
 return { response, xp }
})

ipcMain.handle('state:get', () => {
 return { memory, xp }
})

ipcMain.handle('vault:encrypt', (e, data) => encrypt(data))
ipcMain.handle('vault:decrypt', (e, data) => decrypt(data))

// ============================================================================
// electron/preload.js
// ============================================================================
import { contextBridge, ipcRenderer } from 'electron'

contextBridge.exposeInMainWorld('neural', {
 sendLLM: (payload) => ipcRenderer.invoke('llm:send', payload),
 getState: () => ipcRenderer.invoke('state:get'),
 encrypt: (d) => ipcRenderer.invoke('vault:encrypt', d),
 decrypt: (d) => ipcRenderer.invoke('vault:decrypt', d)
})

// ============================================================================
// renderer/index.html
// ============================================================================
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8" />
<title>NeuralShell Unified</title>
<link rel="stylesheet" href="styles.css" />
</head>
<body>
<div id="app">
 <div id="chat"></div>
 <input id="prompt" placeholder="Enter prompt" />
 <button id="sendBtn">Send</button>
 <div id="xp"></div>
</div>
<script type="module" src="ui.js"></script>
</body>
</html>

// ============================================================================
// renderer/ui.js
// ============================================================================

const chat = document.getElementById('chat')
const sendBtn = document.getElementById('sendBtn')
const xpDiv = document.getElementById('xp')

async function updateState() {
 const state = await window.neural.getState()
 xpDiv.innerText = `XP: ${state.xp.total} | Level: ${state.xp.level}`
}

sendBtn.addEventListener('click', async () => {
 const prompt = document.getElementById('prompt').value
 const { response } = await window.neural.sendLLM({
 provider: 'ollama',
 model: 'llama3',
 prompt
 })

 chat.innerHTML += `<div><b>You:</b> ${prompt}</div>`
 chat.innerHTML += `<div><b>AI:</b> ${response}</div>`
 updateState()
})

updateState()

