ont-size:0.7rem;">XP Threshold:</label> <input type="number" id="autoTriggerXP" placeholder="XP"><br> <button id="startAutoTriggerBtn" class="btn" style="margin-top:4px;">Start AutoTrigger</button> </div> </details> <!-- History Loader --> <details> <summary>History Loader</summary> <div class="panelContent"> <input type="file" id="historyFiles" multiple accept=".txt,.json,.zip"><br> <div id="historyList" style="font-size:0.7rem; max-height:80px; overflow-y:auto;"></div> <button id="injectHistoryBtn" class="btn" style="margin-top:4px;">Inject Selected</button> </div> </details> <!-- PhaseLock --> <details> <summary>PhaseLock</summary> <div class="panelContent"> <input type="password" id="phaseKeyInput" placeholder="Founder key" style="width:100%;"><br> <button id="lockPhaseBtn" class="btn" style="margin-top:4px;">Lock</button> <button id="unlockPhaseBtn" class="btn" style="margin-top:4px;">Unlock</button> <p id="phaseLockStatus" style="font-size:0.7rem;"></p> </div> </details> <!-- Tier Finalizer --> <details> <summary>Tier Finalizer</summary> <div class="panelContent"> <button id="finalizeTiersBtn" class="btn">Finalize Tiers</button> </div> </details> <!-- Feedback --> <details> <summary>Feedback</summary> <div class="panelContent" id="feedbackPanel" style="font-size:0.7rem;"></div> </details> <!-- NeuralDrive --> <details> <summary>NeuralDrive</summary> <div class="panelContent"> <button id="backupBtn" class="btn">Backup Now</button> </div> </details> <!-- Token Auth --> <details> <summary>Token Auth</summary> <div class="panelContent"> <button id="generateTokenBtn" class="btn">Generate Token</button> <p id="tokenDisplay" style="font-size:0.7rem;"></p> </div> </details> <!-- Verify Build --> <details> <summary>Verify Build</summary> <div class="panelContent"> <button id="verifyBtn" class="btn">Run Verification</button> <pre id="verifyResult" style="font-size:0.6rem; white-space:pre-wrap; max-height:80px; overflow-y:auto;"></pre> </div> </details> <!-- Auto Cloak -