')); }); clearLogBtn.addEventListener('click', () => { logs = []; renderLogs(); }); // Dev info update setInterval(() => { devInfo.textContent = `Tasks: ${tasks.length}, Logs: ${logs.length}, Memory: ${memory.length}`; }, 2000); phaseSelect.addEventListener('change', () => { log(`Phase view set to ${phaseSelect.value}`); }); // DOM AI actions injectScriptBtn.addEventListener('click', () => { log('DOM AI: injected script'); addTask('DOM AI inject'); tierFlash(); }); scanInterfaceBtn.addEventListener('click', () => { const modules = document.querySelectorAll('details').length; log(`DOM AI: scanned interface (${modules} modules)`); addTask(`DOM AI scan: ${modules} modules`); }); activateModuleBtn.addEventListener('click', () => { log('DOM AI: activated module'); addTask('DOM AI activate'); flashChat(); }); // Vault drag/drop and decrypt [localPane, vaultPane].forEach(pane => { pane.addEventListener('dragover', evt => { evt.preventDefault(); pane.classList.add('dragover'); }); pane.addEventListener('dragleave', () => { pane.classList.remove('dragover'); }); pane.addEventListener('drop', evt => { evt.preventDefault(); pane.classList.remove('dragover'); const data = evt.dataTransfer.getData('text/plain'); const item = document.getElementById(data); if (item && !item.classList.contains('locked')) { pane.appendChild(item); updateVaultState(); log(`Moved ${item.dataset.name} to ${pane.id === 'localPane' ? 'Local' : 'Vault'}`); addTask(`File moved: ${item.dataset.name}`); } }); }); function createFileItem(name, locked) { const div = document.createElement('div'); div.textContent = name; div.className = 'fileItem' + (locked ? ' locked' : ''); div.dataset.name = name; div.id = `file-${name.replace(/[^a-zA-Z0-9_-]/g, '')}-${Math.random().toString(36).substr(2, 5)}`; div.draggable = !locked; if (!locked) { div.addEventListener('dragstart', evt => { evt.dataTransfer.setData('text/plain', div.id); }); } // decrypt button for locked files const btn = document.createElement('button'); btn.textContent = locked ? 'Decrypt' : 'Open'; btn.addEventListener('click', evt => { evt.stopPropagation(); if (locked) { div.classList.remove('locked'); btn.textContent = 'Open'; log(`Decrypted ${name}`); } else { log(`Opened ${name}`); // If this is a saved chat log, load its content into chat and timeline const fileObj = vaultLocal.concat(vaultRemote).find(it => it.name === name); if (fileObj && fileObj.content) { const lines = fileObj.content.split('
