cument.getElementById('verifyResult'); const cloakToggle = document.getElementById('cloakToggle'); const cleanMemoryBtn = document.getElementById('cleanMemoryBtn'); const activatePhoenixBtn = document.getElementById('activatePhoenixBtn'); // Timers let chatPlaybackInterval = null; let autopilotInterval = null; // Initialise UI sessionStartSpan.textContent = `Started: ${new Date(startTime).toLocaleString()}`; setInterval(() => { const seconds = Math.floor((Date.now() - startTime) / 1000); const hrs = Math.floor(seconds / 3600); const mins = Math.floor((seconds % 3600) / 60); const secs = seconds % 60; sessionRuntimeSpan.textContent = `Runtime: ${hrs}h ${mins}m ${secs}s`; devHoursSpan.textContent = `Dev Hours: ${(seconds / 3600).toFixed(2)}`; }, 1000); // Load vault from localStorage if present function loadVault() { try { const data = JSON.parse(localStorage.getItem('neuralVault') || '{}'); vaultLocal = data.local || []; vaultRemote = data.remote || []; } catch (e) { vaultLocal = []; vaultRemote = []; } renderVault(); } function saveVault() { const data = { local: vaultLocal, remote: vaultRemote }; localStorage.setItem('neuralVault', JSON.stringify(data)); log('Vault saved'); } saveVaultBtn.addEventListener('click', saveVault); loadVaultBtn.addEventListener('click', loadVault); // Render vault lists function renderVault() { localPane.innerHTML = '<h4>Local</h4>'; vaultPane.innerHTML = '<h4>Vault</h4>'; vaultLocal.forEach(item => { localPane.appendChild(createFileItem(item.name, item.locked)); }); vaultRemote.forEach(item => { vaultPane.appendChild(createFileItem(item.name, item.locked)); }); // update Deep Vault recall list refreshDeepVault(); } // Save and update after drop events function updateVaultState() { vaultLocal = []; vaultRemote = []; localPane.querySelectorAll('.fileItem').forEach(el => { vaultLocal.push({ name: el.dataset.name, locked: el.classList.contains('locked') }); }); vaultPane.querySelectorAll('.fileItem').forEach(el => { vaultRemote.push({ name: el.dataset.name, locked: el.classList.contains('locked') }); }); } // Connect LLM (auto detect on load) async function autoDetectLLM() { try { const resp = await fetch('http://127.0.0.1:11434'); if (resp.ok) { llmStatus.textContent = 'Ollama Detected'; llmStatus.style.color = 'var(--highlight)'; } } catch (e) { // remain disconnected } } autoDetectLLM(); connectBtn.addEventListener('click', () => { if (!llmConnected) { llmConnected = true; const mode = (useLocalToggle && useLocalToggle.checked) ? 'Local' : 'Remote'; const modelName = llmSelect.options[llmSelect.selectedIndex].text; llmStatus.textContent = `${mode} connected: ${modelName}`; llmStatus.style.color = 'var(--highlight)'; log(`Connected to ${mode} ${llmSelect.value}`); } }); // Send LLM command sendBtn.addEventListener('click', () => { const cmd = llmInput.value.trim(); if (!cmd) return; // GuardianLoop: prevent sending identical prompt repeatedly if (cmd === lastPrompt) { log('GuardianLoop prevented repeated prompt'); return; } lastPrompt = cmd; lastActionTime = Date.now(); log(`LLM prompt: ${cmd}`); addTask(`LLM: ${cmd}`); appendChatMessage(cmd, 'user'); llmInput.value = ''; const start = Date.now(); updateStatus('thinking'); sendLLM(cmd).then(resp => { const duration = (Date.now() - start) / 1000; updateStatus('done'); const tokens = countTokens(resp); tokenCount.textContent = `${tokens} tokens`; appendChatMessage(resp, 'system'); log(`LLM response (${tokens} tokens, ${duration.toFixed(1)}s): ${resp}`); }); detectTier(cmd); }); // Ritual trigger ritualTrigger.addEventListener('click', () => { const ritual = ritualSelect.value; log(`Ritual triggered: ${ritual}`); addTask(`Ritual: ${ritual}`); triggerRitual(ritual); }); // Toggle actions audioToggle.addEventListener('change', () => { log(`Audio FX ${audioToggle.checked ? 'enabled' : 'disabled'}`); }); glowToggle.addEventListener('change', () => { log(`Glow FX ${glowToggle.checked ? 'enabled' : 'disabled'}`); }); nightToggle.addEventListener('change', () => { document.body.classList.toggle('nightvision', nightToggle.checked); log(`Night vision ${nightToggle.checked ? 'on' : 'off'}`); }); typewriterToggle.addEventListener('change', () => { log(`Typewriter mode ${typewriterToggle.checked ? 'on' : 'off'}`); }); autopilotToggle.addEventListener('change', () => { autopilotActive = autopilotToggle.checked; if (autopilotActive) { startAutopilot(); log('Autopilot enabled'); } else { stopAutopilot(); log('Autopilot disabled'); } }); // Task memory actions saveTasksBtn.addEventListener('click', () => { downloadFile('task_history.txt', tasks.map(t => t.desc).join('
